import { useCallback, useState } from 'react';

/**
 * A hook that returns a string of all the unique IDs in a set and a function to add an ID to the set.
 *
 * @returns {[string | undefined, function]} A tuple containing: (1) ids - A string of all the IDs in the set, or undefined if empty, and (2) addId - A function to add an ID to the set.
 */

const useSetIds = () => {
  const [idSet, setIdSet] = useState(new Set());
  const ids = idSet.size > 0 ? Array.from(idSet).join(' ') : undefined;
  const addId = useCallback(id => {
    setIdSet(previousIds => {
      const clonedSet = new Set(previousIds);
      clonedSet.add(id);
      return clonedSet;
    });
    return () => {
      setIdSet(previousIds => {
        const clonedSet = new Set(previousIds);
        clonedSet.delete(id);
        return clonedSet;
      });
    };
  }, []);
  return [ids, addId];
};
export default useSetIds;