import type { Format } from '../schema.js';
import type { LoaderFunction } from './index.js';
import { SQS_LOADER_WIDTHS } from './loaderWidths.js';

const getSrcSet = (src: string, format: Format): string => {
  return SQS_LOADER_WIDTHS.map((width) => `${src}_${width}.${format} ${width}w`).join(
    ', ',
  );
};

export const useVimeoLoader: LoaderFunction<'vimeo'> = ({ src, format }) => ({
  src: src,
  srcSet: getSrcSet(src, format),
});
