export const filterProps = props =>
// Strip data-* and id attributes from rest props; therefore
// data-test/data-testId/data-*/id aren't spread to both elements.
Object.keys(props).reduce((accum, key) => {
  if (!key.startsWith('data-') && key !== 'id') {
    accum[key] = props[key];
  }
  return accum;
}, {});