import type { Format } from '../schema.js';
import type { LoaderFunction } from './index.js';

const widthToImagePrefix: Record<number, string> = {
  120: '',
  320: 'mq',
  480: 'hq',
  640: 'sd',
};

const recordKeys = <K extends PropertyKey, T>(object: Record<K, T>): Array<K> => {
  return Object.keys(object) as (K)[];
};

const toBase = (videoId: string, format: Format): string =>
  `https://i.ytimg.com/vi${format === 'webp' ? '_webp' : ''}/${videoId}`;

const getSrcSet = (videoId: string, format: Format): string => {
  return recordKeys(widthToImagePrefix).map((width) =>
    `${toBase(videoId, format)}/${widthToImagePrefix[width]}default.${format} ${width}w`
  ).join(
    ', ',
  );
};

export const useYoutubeLoader: LoaderFunction<'youtube'> = ({ videoId, format, src }) => ({
  src: src ?? `${toBase(videoId, format)}/default.${format}`,
  srcSet: getSrcSet(videoId, format),
});
