import { RelativeTimeField } from '@phensley/cldr-types';
export const getRelativeTimeFieldForWeekday = date => {
  const weekdays = [RelativeTimeField.SUN, RelativeTimeField.MON, RelativeTimeField.TUE, RelativeTimeField.WED, RelativeTimeField.THU, RelativeTimeField.FRI, RelativeTimeField.SAT];
  return weekdays[date.dayOfWeek() - 1];
};

/**
 * Adds a time part to an already formatted date.
 * For example: "Wednesday" -> "Wednesday, 4:17 PM".
 */
export const addTimeToFormattedDate = (cldr, date, formattedDatePart) => {
  const formattedTimePart = cldr.Calendars.formatDate(date, {
    time: 'short'
  });
  return cldr.Calendars.formatDateWrapper(formattedDatePart, formattedTimePart, {
    atTime: false,
    width: 'full'
  });
};