/**
 * window.matchMedia expects media queries to NOT include
 * `@media`, while CSS expects media queries to include
 * `@media`. In turn, the media queries on the theme have
 * `@media`, but those in tokens do not.
 *
 * We normalize them here, to handle receiving our media
 * queries being passed from both sources.
 *
 * @param rule
 */
export const normalizeMediaQuery = rule => typeof rule === 'string' && rule.startsWith('@media') ? rule.replace('@media', '').trim() : rule;

/**
 * Given an object containing media queries, evaluates
 * them, and returns an object containing the name and
 * matched rule according to the current window.
 *
 * @param breakpoints {Object}
 */
export const getBreakpoint = function (breakpoints) {
  let windowArg = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : window;
  const breakpointsArr = Object.entries(breakpoints);
  let breakpointIndex = breakpointsArr.findIndex(_ref => {
    let [, rule] = _ref;
    return windowArg.matchMedia(normalizeMediaQuery(rule))?.matches;
  });
  if (breakpointIndex === -1) {
    breakpointIndex = breakpointsArr.length - 1;
  }
  const [name, rule] = breakpointsArr[breakpointIndex];
  const [platform, scale] = name.split('-');
  return {
    name,
    platform,
    rule,
    scale
  };
};