/**
 * Resolve value value based on a breakpoint match. Keys match the keys passed into the Theme.
 * If there's no match, default to the value mapped to by the "_" key.
 */

/**
 * Helper to pass "Mobile" and "Desktop" values to responsive rules
 */
export const createMobileDesktopResponsive = (mobileValue, desktopValue) => ({
  _: desktopValue,
  'mobile-*': mobileValue
});

/**
 * Export the above breakpoints as media queries,
 * prepending "@media " to each breakpoint value
 */
export const getBreakpointsAsMediaQueries = breakpoints => {
  const map = {};
  for (const name in breakpoints) {
    map[name] = `@media ${breakpoints[name]}`;
  }
  return map;
};