import { toSizesString, toSrcSetString } from '@/propStringHelpers.js';
import React, { useEffect, useRef, useState } from 'react';
import type { Sizes, SrcSet } from '../../types/types.js';
import { combineWithDefaultStyle } from '../combineWithDefaultStyle.js';
import { getPassthroughProps } from '../extractPassthroughProps.js';
import { useLoader } from '../loaders/index.js';
import type { ImageProps, Loader, SquarespaceLoader } from '../schema.js';
import {
  type ImageSourceProps,
  type MediaSourceGroup,
  Picture,
  type ReducedImageProps,
  type Sources,
  type TypeSourceGroup,
} from './Picture.js';

/** Hook to validate image component props */
function useValidate<L extends Loader = SquarespaceLoader>(props: ImageProps<L>) {
  const [messages, setMessages] = useState<string[]>([]);

  useEffect(() => {
    if (props.debug) {
      import('../debug/validator.js').then(({ validate, log }) => {
        const latestMessages = validate(props);
        setMessages(latestMessages);
        log(latestMessages);
      });
    }
  }, [props]);

  return messages;
}

function Image<L extends Loader = SquarespaceLoader>(props: ImageProps<L>): JSX.Element {
  const loader: Loader = props.loader ?? 'sqs';
  const { src, srcSet: srcSetProp } = useLoader(loader, props);
  const srcSet = srcSetProp ? toSrcSetString(srcSetProp as SrcSet | string) : srcSetProp;
  const sizes = props.sizes ? toSizesString(props.sizes as Sizes | string) : props.sizes;
  const style = combineWithDefaultStyle(props.style);

  const ref = useRef<HTMLImageElement>(null);
  useValidate(props);

  // in case element exists on first render (isomorphism), run a one-time check for finished loading
  useEffect(() => {
    const imgElement = ref.current;

    if (
      imgElement === null
      || !imgElement.complete
      // HTMLElementImage.complete is true for a variety of reasons -- ensure a source is provided
      || (!imgElement.src && !imgElement.srcset)
    ) {
      return;
    }

    props.onLoadingComplete?.();
  }, []);

  return (
    <img
      ref={ref}
      src={src}
      srcSet={srcSet}
      width={props.width}
      height={props.height}
      alt={props.alt}
      className={props.className}
      style={combineWithDefaultStyle(style)}
      onLoad={props.onLoadingComplete ? (): unknown => props.onLoadingComplete?.() : undefined}
      decoding='async'
      loading={props.loading ?? (props.priority === 'high' ? 'eager' : 'lazy')}
      fetchpriority={props.fetchpriority ?? props.priority}
      data-loader={loader}
      sizes={sizes}
      data-image-component={__PKG_VERSION__}
      {...getPassthroughProps(props)}
    />
  );
}

export { Image as default, Picture };

export type {
  ImageSourceProps,
  MediaSourceGroup,
  ReducedImageProps,
  Sizes,
  Sources,
  SrcSet,
  TypeSourceGroup,
};
