import type { Format, ImageProps, Loader, VimeoLoader, YoutubeLoader } from '../schema.js';
import { useSqsLoader } from './sqs.js';
import { useVimeoLoader } from './vimeo.js';
import { useYoutubeLoader } from './youtube.js';

type FormatLoaderProps = { format: Format };
type VideoIdProp = { videoId: string };
type YoutubeExtraProps = FormatLoaderProps & VideoIdProp & { src?: ImageProps<'youtube'>['src'] };
type LoaderProps<L extends Loader> =
  & {
    srcSet?: ImageProps<L>['srcSet'];
  }
  & (L extends VimeoLoader ? FormatLoaderProps : NonNullable<unknown>)
  & (L extends YoutubeLoader ? YoutubeExtraProps : { src: ImageProps<L>['src'] });
export type LoaderFunction<L extends Loader> = (props: LoaderProps<L>) => LoaderProps<'raw'>;

const useRawLoader: LoaderFunction<'raw'> = ({ src = '', srcSet }) => ({ src, srcSet });

/**
 * Pixel density descriptors are not supported.
 */
export const useLoader = (
  loader: Loader,
  props: LoaderProps<typeof loader>,
): LoaderProps<'raw'> => {
  switch (loader) {
    case 'sqs':
      return useSqsLoader(<LoaderProps<'sqs'>> props);
    case 'raw':
      return useRawLoader(<LoaderProps<'raw'>> props);
    case 'vimeo':
      return useVimeoLoader(<LoaderProps<'vimeo'>> props);
    case 'youtube':
      return useYoutubeLoader(<LoaderProps<'youtube'>> props);
    default:
      // unknown loader, return src if provided
      return { src: props.src ?? '' };
  }
};
