import memoize from 'lodash/memoize';
const splitOnTokens = /({[^}]+})/g;
const matchTokenName = /{([^}]+)}/;

/**
 * Splits a string on tokens; essentially precompiling the template.
 * tokenize("Hello, {friend}! My name is {name}.")
 * // => ['Hello, ', '{friend}', '! My name is ', '{name}']
 *
 * @param template The string to tokenize.
 * @return The string represented as a simple array.
 */
const tokenize = memoize(template => template.split(splitOnTokens));
const replacementsCacheKey = (tokenizedTemplate, substitutions) => `${tokenizedTemplate.join('')}-${JSON.stringify(substitutions)}`;

/**
 * Given a template, make all the replacements at once and return
 * a string.
 * replaceTokens('Hello, ', '{friend}', '! My name is ', '{name}'], { name: 'Jacob' })
 * // => 'Hello {friend}! My name is Jacob'
 *
 * @param tokenizedTemplate The template array.
 * @param substitutions A hash of replacements to make.
 * @return The re-hydrated string.
 */
const replaceTokens = memoize((tokenizedTemplate, substitutions) => tokenizedTemplate.map(templatePart => {
  const tokenMatch = templatePart.match(matchTokenName);
  return tokenMatch && substitutions[tokenMatch[1]] ? substitutions[tokenMatch[1]] : templatePart;
}).join(''), replacementsCacheKey);

/**
 * Given a string and an object, format the string as we'd like.
 * Currently this template language is super dumb, intentionally so.
 * The only replacements allowed are `{key}` substitutions.
 *
 * @param template The string to format
 * @param substitutions An object of replacements.
 * @return The formatted string.
 */
export const substituteStrings = (template, substitutions) => {
  const tokenizedTemplate = tokenize(template);
  return replaceTokens(tokenizedTemplate, substitutions);
};