import { marketingColors } from './colors.marketing';
import { defaultColors } from './colors.default';

/**
 * The raw default color token object shape, exported for backwards compatibility.
 * Consumers working with the full theme (including semantic aliases) should use {@link ThemeColors} instead.
 */

/**
 * The set of all color token strings (e.g. "black", "gray.100", "red.200", etc.).
 * We exclude MarketingColorTokens from this type, as consumers should only use the marketing color aliases (e.g. "marketing.schist.bg.base", "marketing.stone.fg.text", etc.) instead of the raw color tokens.
 */

export const colors = {
  ...defaultColors,
  ...marketingColors
};