import type { LoaderFunction } from './index.js';
import { SQS_LOADER_WIDTHS } from './loaderWidths.js';

const sqsLoader = ({ src, width }: { src: string; width: number }): string =>
  `${src}?format=${width}w`;

export const useSqsLoader: LoaderFunction<'sqs'> = ({ src }) => {
  return {
    src,
    srcSet: SQS_LOADER_WIDTHS.map((width) => {
      const sqsSrc = sqsLoader({ src, width });
      return `${sqsSrc} ${width}w`;
    }).join(', '),
  };
};
