import React from 'react';
import isEqual from 'lodash/isEqual';
export const getSelectedIndex = (items, value) => {
  if (value === undefined) {
    return 0;
  }
  const index = items.findIndex(item => isEqual(item, value));
  return index === -1 ? 0 : index;
};
export const useOptions = children => React.Children.map(children, child => {
  const {
    value
  } = child.props;
  return value;
});