import type { Sizes, SrcSet } from '../types/types.js';

const toMediaQueryString = (mediaQuerySizes: Sizes['mediaQuerySizes']) =>
  (mediaQuerySizes?.length ?? 0) > 0
    ? `${mediaQuerySizes?.map(([src, width]) => `${src} ${width}`).join(', ')}, `
    : '';

export const toSrcSetString = (srcSet: SrcSet | string): string =>
  typeof srcSet === 'string' ? srcSet : srcSet.map(([src, width]) => `${src} ${width}`).join(', ');

export const toSizesString = (sizes: Sizes | string): string =>
  typeof sizes === 'string'
    ? sizes
    : `${toMediaQueryString(sizes.mediaQuerySizes)}${sizes.defaultWidth}`;
