import { shouldForwardProp as isNotStyledSystemProp } from '@sqs/rosetta-styled-system';
import isPropValid from '@emotion/is-prop-valid';
import { isValidEventRegistrationProp } from './eventRegistrationPropNames';

/**
 * Re-export from here so all validators can be accessed from one place.
 */
export { isValidEventRegistrationProp, isNotStyledSystemProp };

/**
 * @emotion/is-valid-prop has special casing that allows through
 * all props that follow a pattern of onX.
 *
 * https://github.com/emotion-js/emotion/blob/main/packages/is-prop-valid/src/index.js#L12
 *
 * We want to negate that behavior, as it allows through invalid
 * props to DOM elements resulting in warnings. E.g. onSelectOption
 * would be passed to a div. So we reverse it here, and leave ensuring
 * whether event prop names are being used to `isValidEventRegistrationProp`.
 */
export const isValidHtmlElementProp = propName => isPropValid(propName) && (propName.charCodeAt(0) !== 111 || propName.charCodeAt(1) !== 110 || propName.charCodeAt(2) > 91);
export const shouldForwardProp = propName => isNotStyledSystemProp(propName) && (isValidHtmlElementProp(propName) || isValidEventRegistrationProp(propName));