import { useTheme } from '@sqs/rosetta-styled';
import { useMemo } from 'react';

/**
 * Determine when a medium dialog will shift to the small size,
 * so you can change the dialog content styles responsively.
 */
export const useSizeMediaQuery = () => {
  const {
    sizes
  } = useTheme();
  const width = sizes.sizes[900];
  const widthQueries = useMemo(() => [`@media (max-width: calc(${width} - 1px))`, `@media (min-width: ${width})`], [width]);
  return widthQueries;
};