// Map prefix to next ID
const nextIdMap = new Map();

/**
 * Create a unique ID for the given prefix. Useful for generating group names
 * for radio groups and unique id/htmlFor pairs. Call in the component
 * constructor or in componentWillMount
 *
 * e.g.
 * ('StringField') => 'StringField-1'
 * ('StringField') => 'StringField-2'
 * ('TabsField') => 'TabsField-1'
 * ('StringField') => 'StringField-3'
 * ('TabsField') => 'TabsField-2'
 *
 * @param {string} prefix
 */
const getNextId = prefix => {
  const nextId = nextIdMap.get(prefix) || 1;
  nextIdMap.set(prefix, nextId + 1);
  return `${prefix}-${nextId}`;
};
export default getNextId;