import type { Writable } from 'type-fest';
import type { ImageProps, Loader } from './schema.js';

type PassthroughProps = Readonly<{ [prop: string]: unknown }>;

const SPECIFIED_IMAGE_PROPS: ReadonlyArray<keyof ImageProps<Loader>> = [
  'alt',
  'className',
  'height',
  'loader',
  'onLoadingComplete',
  'priority',
  'src',
  'srcSet',
  'style',
  'width',
  'debug',
  'format',
  'videoId',
  'sizes',
] as const;
const SPECIFIED_IMAGE_PROPS_SET = new Set(SPECIFIED_IMAGE_PROPS);

export function getPassthroughProps(props: Partial<ImageProps<Loader>>): PassthroughProps {
  const passthrough: Writable<PassthroughProps> = {};
  for (const prop in props) {
    if (!SPECIFIED_IMAGE_PROPS_SET.has(prop)) {
      passthrough[prop] = props[prop];
    }
  }
  return passthrough;
}
