export const expandHitSlop = hitSlop => {
  if (hitSlop === undefined || hitSlop === null) {
    return {};
  }
  if (typeof hitSlop === 'number' || typeof hitSlop === 'string') {
    return {
      bottom: hitSlop,
      left: hitSlop,
      right: hitSlop,
      top: hitSlop
    };
  }
  return hitSlop;
};