import { useEffect } from 'react';
import { useId } from './useId';

/**
 * A hook that adds an ID to a set and returns the resolved ID. If no ID is provided, a generated ID is added to the set and returned. If an ID is provided, it is added to the set and returned.
 *
 * @param {function} addId - A function to add an ID to a set.
 * @param {string} id - An optional ID to use instead of the generated ID.
 * @returns {string} resolvedId - The resolved ID. This is the ID that was added to the set.
 */

const useAddIdToSet = (addId, id) => {
  const defaultId = useId();
  const resolvedId = id ?? defaultId;
  useEffect(() => {
    const removeId = addId(resolvedId);
    return removeId;
  }, [addId, resolvedId]);
  return resolvedId;
};
export default useAddIdToSet;