import React from 'react';
import type { Except } from 'type-fest';
import type { Sizes, SrcSet } from '../../types/types.js';
import { combineWithDefaultStyle } from '../combineWithDefaultStyle.js';
import { getPassthroughProps } from '../extractPassthroughProps.js';
import { toSizesString, toSrcSetString } from '../propStringHelpers.js';
import type { ImageProps } from '../schema.js';
import Image from './index.js';

export type ImageSourceProps = {
  // special version for metadata
  srcSet: SrcSet;

  // shared with Image
  width: number;
  height: number;

  className?: string;
  style?: {
    [x: string]: string | number;
  };
};

type MediaSourceProps = { media: string } & ImageSourceProps;
type TypeSourceProps = { type: string } & ImageSourceProps;

type GroupedTypeSources = TypeSourceProps[] | [...TypeSourceProps[], ImageSourceProps];
type GroupedMediaSources = MediaSourceProps[] | [...MediaSourceProps[], ImageSourceProps];

export type MediaSourceGroup = { media: string; srcs: GroupedTypeSources };
export type TypeSourceGroup = { type: string; srcs: GroupedMediaSources };

export type Sources =
  | [...MediaSourceGroup[], ImageSourceProps]
  | [...TypeSourceGroup[], ImageSourceProps]
  | [ImageSourceProps];

export type ReducedImageProps = Except<
  ImageProps<'raw'>,
  'src' | 'width' | 'height' | 'sizes' | 'srcSet'
>;

type Props = {
  // last element of src array is default img props
  srcs: Sources;
  sizes: Sizes;
} & ReducedImageProps;

const isImageSourceProps = (
  props: MediaSourceGroup | TypeSourceGroup | ImageSourceProps,
): props is ImageSourceProps => !('media' in props) && !('type' in props);

const isMediaSourceGroup = (props: MediaSourceGroup | TypeSourceGroup): props is MediaSourceGroup =>
  'media' in props;

export const Picture = (
  { srcs, className, style, sizes, ...props }: Props,
): JSX.Element => {
  const sizesString = toSizesString(sizes);
  return (
    <picture
      className={className}
      style={combineWithDefaultStyle(style)}
      data-picture-component={__PKG_VERSION__}
    >
      {srcs.map((srcProps) => {
        if (!isImageSourceProps(srcProps)) {
          const groupCriterion = isMediaSourceGroup(srcProps)
            ? { media: srcProps.media }
            : { type: srcProps.type };
          return srcProps.srcs.map(({ srcSet, ...inGroupSourceProps }) => {
            const srcSetString = toSrcSetString(srcSet);
            return (
              <source
                sizes={sizesString}
                srcSet={srcSetString}
                key={srcSetString}
                {...groupCriterion}
                {...inGroupSourceProps}
              />
            );
          });
        } else {
          const { srcSet, ...sourceProps } = srcProps;
          const passthrough = getPassthroughProps(props);
          return (
            <Image
              alt={props.alt}
              debug={props.debug}
              loader='raw'
              onLoadingComplete={props.onLoadingComplete}
              priority={props.priority}
              src={srcSet[srcSet.length - 1]?.[0] ?? ''}
              srcSet={toSrcSetString(srcSet)}
              sizes={sizesString}
              key='image'
              {...sourceProps}
              {...passthrough}
            />
          );
        }
      })}
    </picture>
  );
};
