import { useIsMobile } from './useIsMobile';
import { useSimpleTruncation } from './useSimpleTruncation';
export const useResponsiveTruncation = crumbs => {
  const isMobile = useIsMobile();
  const hideFirstCrumb = !isMobile;
  const truncated = [...crumbs];
  if (hideFirstCrumb) {
    truncated.shift();
  }
  return useSimpleTruncation(truncated);
};