import { useMemo } from 'react';

/**
 * Custom hook to calculate tap target spacing of the input based on parent element positioning
 */
export const useTapTargetSpacing = inputRef => {
  const tapTargetSpace = useMemo(() => {
    if (!inputRef?.parentElement) {
      return {
        padding: '0px',
        margin: '0px'
      };
    }
    const parentRect = inputRef.parentElement.getBoundingClientRect();
    const inputRect = inputRef.getBoundingClientRect();
    const spacing = {
      top: inputRect.top - parentRect.top,
      right: parentRect.right - inputRect.right,
      bottom: parentRect.bottom - inputRect.bottom,
      left: inputRect.left - parentRect.left
    };
    return {
      padding: `${spacing.top}px ${spacing.right}px ${spacing.bottom}px ${spacing.left}px`,
      margin: `${-spacing.top}px ${-spacing.right}px ${-spacing.bottom}px ${-spacing.left}px`
    };
  }, [inputRef]);
  return tapTargetSpace;
};