/* global __DEV__ */

const logged = new Set();
const shouldLog = (message, continuous) => __DEV__ && (continuous || !logged.has(message));
const formatVersionMessage = version => typeof version !== 'undefined' ? `This will be removed in ${version}.` : 'This may be removed in the future.';
const logWarning = message => {
  console.warn(message);
  logged.add(message);
};

/**
 * @param {String} message - message to log.
 * @param {Number} version - what library version the deprecated functionality will be removed
 * @param {Boolean} continuous - whether to log on each call. Or just once.
 */
export const deprecation = function (message, version) {
  let continuous = arguments.length > 2 && arguments[2] !== undefined ? arguments[2] : false;
  const output = `Deprecated: ${message} ${formatVersionMessage(version)}`;
  if (!shouldLog(output, continuous)) {
    return;
  }
  logWarning(output);
};

/**
 *
 * Performs a console.warn with specified message
 * @param {String} message - message to log.
 * @param {Boolean} continuous - whether to log on each call. Or just once.
 */
export const warn = function (message) {
  let continuous = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : false;
  if (!shouldLog(message, continuous)) {
    return;
  }
  logWarning(message);
};
export default {
  deprecation,
  warn
};