import React from 'react';
import Option from '../components/Option';
import OptGroup from '../components/OptGroup';

/**
 * Given a ReactNode returns whether it is an instance of
 * a <Dropdown.Option />
 *
 * @param node
 */
export const isSelectOption = node => {
  return /*#__PURE__*/React.isValidElement(node) && node.type === Option;
};

/**
 * Given a ReactNode returns whether it is an instance of
 * a <Dropdown.OptGroup />
 *
 * @param node
 */
export const isSelectOptGroup = node => {
  return /*#__PURE__*/React.isValidElement(node) && node.type === OptGroup;
};