import { useTheme } from '@sqs/rosetta-styled';
import { getBreakpoint } from '@sqs/rosetta-utilities';
export const useIsMobile = () => {
  const {
    breakpoints
  } = useTheme();
  const {
    platform
  } = getBreakpoint(breakpoints);
  const isMobile = platform === 'mobile';
  return isMobile;
};