import React from 'react';
import { getSelectedIndex } from './base';
export const getAriaControls = (value, index) => {
  if (typeof value === 'string') {
    return `${value.replace(/ /g, '-')}-tab`;
  }
  return `${index}-tab`;
};
export const useAnimate = (options, value) => {
  const focusedIndex = getSelectedIndex(options, value);
  const optionsCount = options.length;
  const animateTo = React.useCallback(() => {
    const segmentIncrementPercentageWidth = 100 / optionsCount;
    const defaultedFocusedIndex = focusedIndex === -1 ? 0 : focusedIndex;
    const style = {
      width: segmentIncrementPercentageWidth,
      left: segmentIncrementPercentageWidth * defaultedFocusedIndex
    };
    return {
      ...style,
      left: `${style.left}%`,
      width: `${style.width}%`
    };
  }, [focusedIndex, optionsCount]);
  return {
    animateTo,
    focusedIndex
  };
};