export const useSimpleTruncation = crumbs => {
  const [first, ...truncated] = crumbs;
  const last = truncated.pop();
  const result = [];
  if (first) {
    result.push(first);
  }
  if (truncated.length) {
    result.push(truncated);
  }
  if (last) {
    result.push(last);
  }
  return result;
};