import 'focus-visible';
import { useEffect, useState } from 'react';

/**
 * @param {HTMLElement} ref - A reference to the element that is focusable. Passing `refs` created with `useRef` is not supported as they do not trigger effects and re-renders.
 */
const useFocusVisible = ref => {
  const [isFocused, setIsFocused] = useState(false);
  useEffect(() => {
    if (!ref) {
      return;
    }
    const onFocus = () => setIsFocused(ref.dataset.hasOwnProperty('focusVisibleAdded'));
    const onBlur = () => setIsFocused(false);
    ref.addEventListener('focus', onFocus);
    ref.addEventListener('blur', onBlur);
    return () => {
      ref.removeEventListener('focus', onFocus);
      ref.removeEventListener('blur', onBlur);
    };
  }, [ref]);
  return isFocused;
};
export default useFocusVisible;