import { css as cssThemeResolve } from '@sqs/rosetta-styled-system';
import pick from 'lodash/pick';
import omit from 'lodash/omit';
import platforms from './platforms';

/**
 * Pseudo props can exist on a themed variant definition. To see an example
 * see the button theme definition
 *
 * e.g.
 * Button theme definitions contain a `pseudo` key like so:
 *
 * buttons = {
 *   primary: {
 *     // button styles go here,
 *     pseudo: {
 *       hover: {
 *         // button hover styles here
 *       }
 *     }
 *   }
 * }
 *
 * that can
 * be used to define how the button should behave on focus, hover,
 * and disabled states - basically any css style that is target
 * via a pseudo-selector.
 *
 * We define these states without the css selector `&:` that typically
 * is required by css-in-js becuase we want those definitions to be platform
 * agnostic. Native doesn't know about `&:hover`.
 * This resolver prepends the `&:` key to obtain a style object that looks like
 *  {
 *    '&:hover': {
 *      // hover styles
 *    }
 *  }
 */
const resolveVariantPseudoProps = variant => {
  return Object.entries(variant).reduce((acc, _ref) => {
    let [prop, value] = _ref;
    if (prop === 'pseudo') {
      Object.keys(value).forEach(pseudoKey => {
        acc[`&:${pseudoKey}`] = value[pseudoKey];
      });
    } else {
      acc[prop] = value;
    }
    return acc;
  }, {});
};
